using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SaucyMVC.Data; using SaucyMVC.Models; using SaucyMVC.Services;
namespace SaucyMVC.Controllers;
public class AdminController:BaseController {
 readonly SaucyDbContext _db; readonly OrderWorkflowService _workflow; readonly ReservationAutomationService _reservationAutomation; readonly PasswordHasher<User> _hasher=new(); public AdminController(SaucyDbContext db,OrderWorkflowService workflow,ReservationAutomationService reservationAutomation){_db=db;_workflow=workflow;_reservationAutomation=reservationAutomation;} IActionResult Denied()=>RedirectToAction("Login","Account",new{role="Admin"}); bool OkAdmin()=>IsRole("Admin");
 public async Task<IActionResult> Index(){if(!OkAdmin())return Denied();await _reservationAutomation.ProcessAsync();ViewBag.Users=await _db.Users.CountAsync(x=>x.Role=="Customer");ViewBag.PendingReservations=await _db.Reservations.CountAsync(x=>x.Status=="Pending");ViewBag.ActiveOrders=await _db.Orders.CountAsync(x=>x.Status=="Confirmed"||x.Status=="Preparing"||x.Status=="Ready");ViewBag.PendingPayments=await _db.Payments.CountAsync(x=>x.Status=="Pending");ViewBag.PendingRefunds=await _db.RefundRequests.CountAsync(x=>x.Status=="Pending");ViewBag.PendingCancellations=await _db.Orders.CountAsync(x=>x.CancellationRequestStatus=="Pending");ViewBag.Revenue=await _db.Payments.Where(x=>x.Status=="Paid").SumAsync(x=>(decimal?)x.Amount)??0;var today=DateTime.Today;var tomorrow=today.AddDays(1);ViewBag.Today=await _db.TransactionHistory.Where(x=>x.TransactionDate>=today&&x.TransactionDate<tomorrow).SumAsync(x=>(decimal?)x.TotalAmount)??0;return View();}
 public async Task<IActionResult> Reservations(string? status){if(!OkAdmin())return Denied();await _reservationAutomation.ProcessAsync();var q=_db.Reservations.Include(x=>x.User).Include(x=>x.DiningTable).AsQueryable();if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);ViewBag.Status=status;ViewBag.HoldMinutes=_reservationAutomation.PendingHoldMinutes;ViewBag.NoShowGraceMinutes=_reservationAutomation.NoShowGraceMinutes;return View(await q.OrderByDescending(x=>x.Status=="Pending").ThenBy(x=>x.ReservationDate).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetReservationStatus(int id,string status){
  if(!OkAdmin())return Denied();
  var allowed=new[]{"Declined","Confirmed","Completed","Cancelled"};
  var r=await _db.Reservations.Include(x=>x.DiningTable).FirstOrDefaultAsync(x=>x.Id==id);
  if(r==null||!allowed.Contains(status))return RedirectToAction(nameof(Reservations));
  if(status=="Confirmed"){
   if(!_reservationAutomation.IsLiveHold(r)){_reservationAutomation.Release(r,"Expired");await _db.SaveChangesAsync();TempData["Error"]="This temporary table hold expired. The customer must submit a new request.";return RedirectToAction(nameof(Reservations));}
   if(r.DiningTable==null||!r.DiningTable.IsActive||r.DiningTable.Capacity<r.GuestCount){TempData["Error"]="This table cannot accommodate the reservation. Update the table before confirming.";return RedirectToAction(nameof(Reservations));}
   var start=r.ReservationDate.AddHours(-2);var end=r.ReservationDate.AddHours(2);
   var conflict=await _db.Reservations.AnyAsync(x=>x.Id!=r.Id&&x.DiningTableId==r.DiningTableId&&(x.Status=="Accepted"||x.Status=="Confirmed"||x.Status=="Seated")&&x.ReservationDate>start&&x.ReservationDate<end);
   if(conflict){TempData["Error"]=$"{r.DiningTable.TableNumber} is already confirmed for an overlapping schedule.";return RedirectToAction(nameof(Reservations));}
   if(r.DiningTable.OperationalStatus=="Occupied"&&r.DiningTable.OccupiedUntil.HasValue&&r.DiningTable.OccupiedUntil.Value.AddMinutes(30)>r.ReservationDate){TempData["Error"]=$"{r.DiningTable.TableNumber} is occupied too close to this reservation. Clear or reassign the table first.";return RedirectToAction(nameof(Reservations));}
  }
  if((status=="Completed"||status=="Cancelled")&&r.Status=="Seated"&&r.DiningTable!=null){r.DiningTable.OperationalStatus="Cleaning";r.DiningTable.OccupiedUntil=null;r.DiningTable.CurrentPartySize=null;}
  if(status=="Confirmed")_reservationAutomation.Confirm(r);else if(status=="Declined"||status=="Cancelled")_reservationAutomation.Release(r,status);else r.Status=status;await _db.SaveChangesAsync();
  TempData["Success"]=$"Reservation #{r.Id} is now {status.ToLowerInvariant()}.";
  return RedirectToAction(nameof(Reservations));
 }
 public async Task<IActionResult> DiningTables(){if(!OkAdmin())return Denied();await _reservationAutomation.ProcessAsync();var tables=await _db.DiningTables.OrderBy(x=>x.TableNumber).ToListAsync();var now=DateTime.Now;var ids=tables.Select(x=>x.Id).ToList();var next=await _db.Reservations.Include(x=>x.User).Where(x=>x.DiningTableId!=null&&ids.Contains(x.DiningTableId.Value)&&((x.Status=="Pending"&&x.HoldExpiresAt.HasValue&&x.HoldExpiresAt>now)||x.Status=="Confirmed")&&x.ReservationDate>=now).OrderBy(x=>x.ReservationDate).ToListAsync();ViewBag.NextReservations=next.GroupBy(x=>x.DiningTableId!.Value).ToDictionary(x=>x.Key,x=>x.First());return View(tables);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddDiningTable(string tableNumber,int capacity){if(!OkAdmin())return Denied();if(!string.IsNullOrWhiteSpace(tableNumber)&&capacity>0&&!await _db.DiningTables.AnyAsync(x=>x.TableNumber==tableNumber)){_db.DiningTables.Add(new DiningTable{TableNumber=tableNumber.Trim(),Capacity=capacity});await _db.SaveChangesAsync();}return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ToggleDiningTable(int id){if(!OkAdmin())return Denied();var t=await _db.DiningTables.FindAsync(id);if(t!=null){t.IsActive=!t.IsActive;t.OperationalStatus=t.IsActive?"Available":"Out of Service";t.OccupiedUntil=null;t.CurrentPartySize=null;await _db.SaveChangesAsync();}return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> EditDiningTable(int id,int capacity){if(!OkAdmin())return Denied();var t=await _db.DiningTables.FindAsync(id);if(t!=null&&capacity>0){t.Capacity=capacity;await _db.SaveChangesAsync();}return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteDiningTable(int id){if(!OkAdmin())return Denied();var t=await _db.DiningTables.FindAsync(id);if(t!=null&&!await _db.Reservations.AnyAsync(r=>r.DiningTableId==id)){_db.DiningTables.Remove(t);await _db.SaveChangesAsync();}else TempData["Error"]="The table is referenced by a reservation and cannot be deleted.";return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SeatWalkIn(int id,int partySize,int durationMinutes=90){if(!OkAdmin())return Denied();await _reservationAutomation.ProcessAsync();var t=await _db.DiningTables.FindAsync(id);if(t==null||!t.IsActive||t.OperationalStatus!="Available"){TempData["Error"]="That table is not currently available.";return RedirectToAction(nameof(DiningTables));}if(partySize<1||partySize>t.Capacity){TempData["Error"]=$"{t.TableNumber} can accommodate up to {t.Capacity} guests.";return RedirectToAction(nameof(DiningTables));}durationMinutes=Math.Clamp(durationMinutes,30,180);var now=DateTime.Now;var until=now.AddMinutes(durationMinutes);var next=await _db.Reservations.Where(x=>x.DiningTableId==id&&((x.Status=="Pending"&&x.HoldExpiresAt.HasValue&&x.HoldExpiresAt>now)||x.Status=="Confirmed")&&x.ReservationDate>=now).OrderBy(x=>x.ReservationDate).FirstOrDefaultAsync();if(next!=null&&until.AddMinutes(_reservationAutomation.WalkInTurnoverBufferMinutes)>next.ReservationDate){TempData["Error"]=$"Walk-in blocked: {t.TableNumber} must be ready {_reservationAutomation.WalkInTurnoverBufferMinutes} minutes before the {next.ReservationDate:h:mm tt} reservation.";return RedirectToAction(nameof(DiningTables));}t.OperationalStatus="Occupied";t.CurrentPartySize=partySize;t.OccupiedUntil=until;await _db.SaveChangesAsync();TempData["Success"]=$"Walk-in party seated at {t.TableNumber} until approximately {until:h:mm tt}.";return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ClearTable(int id){if(!OkAdmin())return Denied();var t=await _db.DiningTables.FindAsync(id);if(t!=null&&t.IsActive){t.OperationalStatus="Cleaning";t.OccupiedUntil=null;t.CurrentPartySize=null;await _db.SaveChangesAsync();}return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetTableReady(int id){if(!OkAdmin())return Denied();var t=await _db.DiningTables.FindAsync(id);if(t!=null&&t.IsActive){t.OperationalStatus="Available";t.OccupiedUntil=null;t.CurrentPartySize=null;await _db.SaveChangesAsync();}return RedirectToAction(nameof(DiningTables));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SeatReservation(int id){if(!OkAdmin())return Denied();await _reservationAutomation.ProcessAsync();var r=await _db.Reservations.Include(x=>x.DiningTable).FirstOrDefaultAsync(x=>x.Id==id);if(r==null||r.Status!="Confirmed"||r.DiningTable==null)return RedirectToAction(nameof(Reservations));if(!r.DiningTable.IsActive||r.DiningTable.OperationalStatus!="Available"){TempData["Error"]=$"{r.DiningTable.TableNumber} is not ready. Clear and mark the table ready before seating this reservation.";return RedirectToAction(nameof(Reservations));}var now=DateTime.Now;_reservationAutomation.Seat(r,now);r.DiningTable.OperationalStatus="Occupied";r.DiningTable.CurrentPartySize=r.GuestCount;r.DiningTable.OccupiedUntil=now.AddMinutes(_reservationAutomation.DefaultDiningMinutes);await _db.SaveChangesAsync();TempData["Success"]=$"Reservation #{r.Id} checked in and seated at {r.DiningTable.TableNumber}.";return RedirectToAction(nameof(Reservations));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> MarkNoShow(int id){if(!OkAdmin())return Denied();await _reservationAutomation.ProcessAsync();var r=await _db.Reservations.FindAsync(id);if(r==null||r.Status!="Confirmed")return RedirectToAction(nameof(Reservations));if(DateTime.Now<r.ReservationDate.AddMinutes(_reservationAutomation.NoShowGraceMinutes)){TempData["Error"]=$"The {_reservationAutomation.NoShowGraceMinutes}-minute grace period has not ended yet.";return RedirectToAction(nameof(Reservations));}_reservationAutomation.Release(r,"No-show");await _db.SaveChangesAsync();TempData["Success"]=$"Reservation #{r.Id} marked as no-show; the table is released.";return RedirectToAction(nameof(Reservations));}
 public async Task<IActionResult> Orders(string? status,string? attention){if(!OkAdmin())return Denied();var q=_db.Orders.Include(x=>x.User).Include(x=>x.Reservation).ThenInclude(r=>r!.DiningTable).Include(x=>x.Items).ThenInclude(i=>i.MenuItem).Include(x=>x.StatusHistory).AsSplitQuery().AsQueryable();if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);if(attention=="cancellation")q=q.Where(x=>x.CancellationRequestStatus=="Pending");ViewBag.Status=status;ViewBag.Attention=attention;ViewBag.OrderQueueVersion=await GetOrderQueueVersionAsync();return View(await q.OrderByDescending(x=>x.CancellationRequestStatus=="Pending").ThenByDescending(x=>x.OrderedAt).ToListAsync());}
 [HttpGet,ResponseCache(NoStore=true,Location=ResponseCacheLocation.None)] public async Task<IActionResult> OrderQueueVersion(){if(!OkAdmin())return Unauthorized();return Json(new{version=await GetOrderQueueVersionAsync(),serverTime=DateTime.Now});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetOrderStatus(int id,string status){if(!OkAdmin())return Denied();var allowed=new[]{"Pending","Confirmed","Preparing","Ready","Completed","Cancelled"};var o=await _db.Orders.FindAsync(id);if(o!=null&&allowed.Contains(status)&&_workflow.ChangeStatus(o,status,CurrentUserId,CurrentUserName,CurrentRole,"Administrative status correction.")){if(status=="Cancelled"&&o.CancellationRequestStatus=="Pending")o.CancellationRequestStatus="Approved";await _db.SaveChangesAsync();TempData["Success"]=$"Order #{o.Id} is now {status.ToLowerInvariant()}.";}return RedirectToAction(nameof(Orders));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ApproveOrderCancellation(int id){if(!OkAdmin())return Denied();var o=await _db.Orders.FindAsync(id);if(o!=null&&o.CancellationRequestStatus=="Pending"&&o.Status!="Completed"&&o.Status!="Cancelled"){o.CancellationRequestStatus="Approved";_workflow.ChangeStatus(o,"Cancelled",CurrentUserId,CurrentUserName,CurrentRole,$"Cancellation approved. Reason: {o.CancellationReason}");await _db.SaveChangesAsync();TempData["Success"]=$"Cancellation approved for order #{o.Id}.";}return RedirectToAction(nameof(Orders),new{attention="cancellation"});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DismissOrderCancellation(int id){if(!OkAdmin())return Denied();var o=await _db.Orders.FindAsync(id);if(o!=null&&o.CancellationRequestStatus=="Pending"){o.CancellationRequestStatus="Dismissed";_workflow.RecordEvent(o,"Cancellation dismissed",CurrentUserId,CurrentUserName,CurrentRole,$"Request was dismissed. Staff reason: {o.CancellationReason}");await _db.SaveChangesAsync();TempData["Success"]=$"Cancellation request dismissed for order #{o.Id}; the order remains {o.Status.ToLowerInvariant()}.";}return RedirectToAction(nameof(Orders),new{attention="cancellation"});}
 public async Task<IActionResult> Menu(){if(!OkAdmin())return Denied();ViewBag.Sauces=await _db.SauceOptions.OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Name).ToListAsync();return View(await _db.MenuItems.OrderBy(x=>x.Category).ThenBy(x=>x.Name).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveMenuItem(int id,string name,string category,decimal price,string? description,string? imagePath,bool isAvailable=true){if(!OkAdmin())return Denied();MenuItem m;if(id==0){m=new MenuItem();_db.MenuItems.Add(m);}else{m=await _db.MenuItems.FindAsync(id)??new MenuItem();}m.Name=name.Trim();m.Category=category.Trim();m.Price=price;m.Description=description??"";m.ImagePath=imagePath;m.IsAvailable=isAvailable;await _db.SaveChangesAsync();return RedirectToAction(nameof(Menu));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ToggleMenuItem(int id){if(!OkAdmin())return Denied();var m=await _db.MenuItems.FindAsync(id);if(m!=null){m.IsAvailable=!m.IsAvailable;await _db.SaveChangesAsync();}return RedirectToAction(nameof(Menu));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ToggleSauce(int id){if(!OkAdmin())return Denied();var sauce=await _db.SauceOptions.FindAsync(id);if(sauce!=null){sauce.IsAvailable=!sauce.IsAvailable;await _db.SaveChangesAsync();TempData["Success"]=$"{sauce.Name} is now {(sauce.IsAvailable?"available":"unavailable")}.";}return RedirectToAction(nameof(Menu));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> RenameSauce(int id,string name){if(!OkAdmin())return Denied();var sauce=await _db.SauceOptions.FindAsync(id);if(sauce!=null&&!string.IsNullOrWhiteSpace(name)){sauce.Name=name.Trim();await _db.SaveChangesAsync();}return RedirectToAction(nameof(Menu));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> EditMenuItem(int id,string name,string category,decimal price,string? description){if(!OkAdmin())return Denied();var m=await _db.MenuItems.FindAsync(id);if(m!=null){m.Name=name.Trim();m.Category=category.Trim();m.Price=price;m.Description=description??"";await _db.SaveChangesAsync();}return RedirectToAction(nameof(Menu));}
 public async Task<IActionResult> Payments(string? status){if(!OkAdmin())return Denied();var q=_db.Payments.Include(x=>x.User).Include(x=>x.Order).AsQueryable();if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);ViewBag.Status=status;return View(await q.OrderByDescending(x=>x.CreatedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> MarkPaymentPaid(int id){if(!OkAdmin())return Denied();var p=await _db.Payments.Include(x=>x.Order).ThenInclude(o=>o!.Items).ThenInclude(i=>i.MenuItem).FirstOrDefaultAsync(x=>x.Id==id);if(p!=null&&p.Status!="Paid"){p.Status="Paid";if(p.Order!=null)_workflow.ChangeStatus(p.Order,"Confirmed",CurrentUserId,CurrentUserName,CurrentRole,"Cash payment verified by administrator.");if(p.OrderId.HasValue&&!await _db.TransactionHistory.AnyAsync(x=>x.OrderId==p.OrderId)){var items=p.Order==null?"":string.Join(", ",p.Order.Items.Select(i=>$"{i.Quantity}x {i.MenuItem?.Name}{(i.Sauce1Name==null?"":$" [{i.Sauce1Name} + {i.Sauce2Name}]")}"));_db.TransactionHistory.Add(new TransactionHistory{UserId=p.UserId,OrderId=p.OrderId,TotalAmount=p.Amount,OrderItems=items,PaymentMethod=p.Method});}await _db.SaveChangesAsync();TempData["Success"]=$"Payment #{p.Id} marked as paid. Order #{p.OrderId} is now confirmed for staff.";}return RedirectToAction(nameof(Payments));}
 public async Task<IActionResult> Refunds(string? status){if(!OkAdmin())return Denied();var q=_db.RefundRequests.Include(x=>x.User).Include(x=>x.Order).AsQueryable();if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);ViewBag.Status=status;return View(await q.OrderByDescending(x=>x.RequestedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetRefundStatus(int id,string status){if(!OkAdmin())return Denied();var r=await _db.RefundRequests.FindAsync(id);if(r!=null&&(status=="Accepted"||status=="Declined")){r.Status=status;await _db.SaveChangesAsync();}return RedirectToAction(nameof(Refunds));}
 public async Task<IActionResult> Transactions(string? search,string? range){if(!OkAdmin())return Denied();var q=_db.TransactionHistory.Include(x=>x.User).AsQueryable();if(range=="today"){var d=DateTime.Today;var n=d.AddDays(1);q=q.Where(x=>x.TransactionDate>=d&&x.TransactionDate<n);}if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.OrderItems.Contains(search)||x.PaymentMethod.Contains(search));ViewBag.Search=search;ViewBag.Range=range;return View(await q.OrderByDescending(x=>x.TransactionDate).ToListAsync());}
 public async Task<IActionResult> Accounts(string? role,string? state){if(!OkAdmin())return Denied();var q=_db.Users.AsQueryable();if(!string.IsNullOrWhiteSpace(role))q=q.Where(x=>x.Role==role);if(state=="inactive")q=q.Where(x=>!x.IsActive);ViewBag.Role=role;ViewBag.State=state;return View(await q.OrderBy(x=>x.Role).ThenBy(x=>x.FullName).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ToggleAccount(int id){if(!OkAdmin())return Denied();var u=await _db.Users.FindAsync(id);if(u!=null&&u.Id!=CurrentUserId){u.IsActive=!u.IsActive;await _db.SaveChangesAsync();}return RedirectToAction(nameof(Accounts));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CreateStaff(string fullName,string email,string password,string role="Staff"){if(!OkAdmin())return Denied();email=email.Trim().ToLowerInvariant();if((role=="Admin"||role=="Staff")&&!await _db.Users.AnyAsync(x=>x.Email==email)){var u=new User{FullName=fullName.Trim(),Email=email,Role=role};u.PasswordHash=_hasher.HashPassword(u,password);_db.Users.Add(u);await _db.SaveChangesAsync();}return RedirectToAction(nameof(Accounts),new{role="Staff"});}
 async Task<string> GetOrderQueueVersionAsync(){var latestOrderId=await _db.Orders.MaxAsync(x=>(int?)x.Id)??0;var latestHistoryId=await _db.OrderStatusHistory.MaxAsync(x=>(int?)x.Id)??0;return $"{latestOrderId}:{latestHistoryId}";}
}
